class SgfTree:
    def __init__(self, properties=None, children=None):
        self.properties = properties or {}
        self.children = children or []

    def __eq__(self, other):
        if not isinstance(other, SgfTree):
            return False
        for key, value in self.properties.items():
            if key not in other.properties:
                return False
            if other.properties[key] != value:
                return False
        for key in other.properties.keys():
            if key not in self.properties:
                return False
        if len(self.children) != len(other.children):
            return False
        for child, other_child in zip(self.children, other.children):
            if child != other_child:
                return False
        return True

    def __ne__(self, other):
        return not self == other


class _Parser:
    def __init__(self, input_string):
        self.input_string = input_string
        self.position = 0

    def eof(self):
        return self.position >= len(self.input_string)

    def peek(self):
        if self.eof():
            return None
        return self.input_string[self.position]

    def next(self):
        character = self.peek()
        if character is not None:
            self.position += 1
        return character

    def expect(self, expected, message):
        if self.peek() != expected:
            raise ValueError(message)
        self.position += 1

    def parse_game_tree(self):
        self.expect("(", "tree missing")
        if self.peek() != ";":
            raise ValueError("tree missing")

        nodes = []
        while self.peek() == ";":
            nodes.append(self.parse_node())

        variations = []
        while self.peek() == "(":
            variations.append(self.parse_game_tree())

        self.expect(")", "tree missing")

        for parent, child in zip(nodes, nodes[1:]):
            parent.children.append(child)
        nodes[-1].children.extend(variations)
        return nodes[0]

    def parse_node(self):
        self.expect(";", "tree missing")
        properties = {}

        while self.peek() not in (None, ";", "(", ")"):
            name, values = self.parse_property()
            properties[name] = values

        return SgfTree(properties=properties)

    def parse_property(self):
        character = self.peek()
        if not self._is_ascii_letter(character):
            raise ValueError("properties without delimiter")

        start = self.position
        while self._is_ascii_letter(self.peek()):
            character = self.next()
            if "a" <= character <= "z":
                raise ValueError("property must be in uppercase")

        name = self.input_string[start:self.position]
        if self.peek() != "[":
            raise ValueError("properties without delimiter")

        values = []
        while self.peek() == "[":
            values.append(self.parse_text_value())
        return name, values

    def parse_text_value(self):
        self.expect("[", "tree missing")
        value = []

        while True:
            character = self.next()
            if character is None:
                raise ValueError("tree missing")

            if character == "\\":
                escaped = self.next()
                if escaped is None:
                    raise ValueError("tree missing")
                if escaped == "\n":
                    continue
                if escaped.isspace():
                    value.append(" ")
                else:
                    value.append(escaped)
                continue

            if character == "]":
                return "".join(value)
            if character == "\n":
                value.append("\n")
            elif character.isspace():
                value.append(" ")
            else:
                value.append(character)

    @staticmethod
    def _is_ascii_letter(character):
        return (
            character is not None
            and ("A" <= character <= "Z" or "a" <= character <= "z")
        )


def parse(input_string):
    parser = _Parser(input_string)
    if parser.peek() != "(":
        raise ValueError("tree missing")

    tree = parser.parse_game_tree()
    if not parser.eof():
        raise ValueError("tree missing")
    return tree

